          fail_ci_if_error: true

  portable-evidence:
    name: Chromium portable evidence
    needs: [linux, desktop, desktop-windows, scope]
    if: ${{ !cancelled() }}
    runs-on: ubuntu-24.04
    timeout-minutes: 10
