      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          fetch-depth: 2
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: ${{ needs.scope.outputs.full }}
          upstream_result: ${{ needs.scope.result }}
      - name: Require all full Chromium shards
        if: ${{ steps.scope.outputs.full == 'true' }}
        env:
          LINUX: ${{ needs.linux.result }}
          DESKTOP: ${{ needs.desktop.result }}
          WINDOWS: ${{ needs.desktop-windows.result }}
        run: |
          test "$LINUX" = success
          test "$DESKTOP" = success
          test "$WINDOWS" = success
      - uses: actions/setup-node@v7.1.0
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          node-version: 22
      - uses: actions/download-artifact@v8
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          pattern: chromium-portable-*-${{ github.run_attempt }}
          path: target/chromium-portable
      - name: Validate every OS and the complete portable inventory
